arguments.command:
python3 -c "import time; import numpy as np; from pycbc.types import TimeSeries, FrequencySeries; from pycbc.filter import matched_filter; from pycbc.psd import aLIGOZeroDetHighPower; 
dt = 1.0/1024; n = 1024 * 128; 
strain = TimeSeries(np.random.randn(n), delta_t=dt); 
hp = TimeSeries(np.random.randn(n), delta_t=dt); 
psd = aLIGOZeroDetHighPower(n//2+1, 1.0/128, 20); 
start = time.time(); 
snr = matched_filter(hp, strain, psd=psd, low_frequency_cutoff=20); 
print(time.time() - start)"

